def test_bidi_ends_on_its_own(stub):
    code = None
    try:
        list(stub.ScorePayments(iter([payment()]), metadata=WALLET, timeout=3))
    except grpc.RpcError as error:
        code = error.code()             # поймали ошибку вызова…
    assert code is None, f"поток не закончился: {code}"   # …и превратили её в assert
